package com.bank.stream.service;

import com.bank.stream.model.Txn;
import java.math.BigDecimal;
import java.util.List;
import java.util.stream.Collectors;

// Stateless: judges each batch alone, keeps no memory across batches.
public class StatelessFilter {

    private final BigDecimal threshold;

    public StatelessFilter(BigDecimal threshold) {
        this.threshold = threshold;
    }

    public List<Txn> keepAboveThreshold(List<Txn> batch) {
        return batch.stream()
                .filter(t -> t.getAmount().compareTo(threshold) >= 0)
                .collect(Collectors.toList());
    }
}
