package com.bank.stream.service;

import com.bank.stream.model.Txn;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;

// Stateful: carries a running per-account count and a seen-id set across batches.
public class StatefulProcessor {

    private final Map<String, Long> runningCount = new LinkedHashMap<>(); // state
    private final Set<String> seenTxnIds = new HashSet<>();               // state

    // Process one batch: skip duplicates, update running counts.
    public Map<String, Long> process(List<Txn> batch) {
        for (Txn t : batch) {
            if (!seenTxnIds.add(t.getTxnId())) {
                continue; // duplicate → stateful dedup drops it
            }
            runningCount.merge(t.getAccountId(), 1L, Long::sum);
        }
        return new LinkedHashMap<>(runningCount); // snapshot of carried state
    }
}
