package com.bank.stream;

import com.bank.stream.model.Txn;
import com.bank.stream.service.StatefulProcessor;
import com.bank.stream.service.StatelessFilter;
import java.math.BigDecimal;
import java.util.List;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

// Runnable demo: stateless forgets each batch; stateful carries state forward.
public class StatefulVsStatelessDemo {

    private static final Logger log = Logger.getLogger(StatefulVsStatelessDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setLevel(Level.ALL);
        handler.setFormatter(new Formatter() {
            @Override public String format(LogRecord r) {
                return String.format("%1$tF %1$tT %2$-7s %3$s%n",
                        new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
            }
        });
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        StatelessFilter filter = new StatelessFilter(new BigDecimal("1000"));
        StatefulProcessor processor = new StatefulProcessor();

        List<Txn> batch1 = List.of(
            new Txn("T1", "SAV2001", new BigDecimal("50000")),
            new Txn("T2", "CUR3001", new BigDecimal("500")),       // filtered out
            new Txn("T3", "SAV2001", new BigDecimal("3000")));
        List<Txn> batch2 = List.of(
            new Txn("T3", "SAV2001", new BigDecimal("3000")),      // duplicate id
            new Txn("T4", "CUR3001", new BigDecimal("9000")));

        var f1 = filter.keepAboveThreshold(batch1);
        log.info(() -> "Stateless filter batch1 kept: " + f1.size() + " rows (no memory)");
        var s1 = processor.process(f1);
        log.info(() -> "Stateful counts after batch1: " + s1);

        var f2 = filter.keepAboveThreshold(batch2);
        log.info(() -> "Stateless filter batch2 kept: " + f2.size() + " rows (no memory)");
        var s2 = processor.process(f2);
        log.info(() -> "Stateful counts after batch2: " + s2 + " (T3 duplicate dropped)");

        log.info("Stateful vs stateless demo complete.");
    }
}
